output.text:
                                                     messages_json,
                                                     CAGENT_MESSAGES_BUFFER_SIZE,
                                                     NULL);
            if (is_budget_error(ret)) {
                int evict_ret = agent_session_evict_oldest_turn(agent, session);
                if (evict_ret == AGENT_OK) {
