#include <unistd.h>

#include <cstdint>
#include <fstream>
#include <memory>

#include "tensorflow/lite/micro/micro_interpreter.h"
#include "tensorflow/lite/micro/micro_mutable_op_resolver.h"
#include "tensorflow/lite/micro/micro_profiler.h"

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void usage(void)
{
  printf("\nUtility to use tflite micro on nuttx.\n"
    "[ -C       ] Compile tflite model into c++ codes.\n"
    "[ -E       ] Do once evaluation (for profiling).\n"
    "[ -i <str> ] Readable model file path.\n"
    "[ -o <str> ] Writable c++ file path.\n"
    "[ -p <str> ] Prefix of compiled code.\n"
    "[ -a <int> ] Arena size (mempool).\n"
    "[ -h       ] Print this message.\n");
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

extern "C" int main(int argc, FAR char* argv[])
{
  const char* modelFileName = nullptr;
  const char* codeFileName = nullptr;
  const char* prefix = "NXAI";
  bool need_compile = false;
  bool need_invoke = false;
  int arenaSize = 1024 * 8;

  int ch;
  while ((ch = getopt(argc, argv, "CEhi:o:p:a:")) != EOF)
    {
      switch (ch)
        {
          case 'C':
            need_compile = true;
            break;
          case 'E':
            need_invoke = true;
            break;
          case 'p':
            prefix = optarg;
            break;
          case 'i':
            modelFileName = optarg;
            break;
          case 'o':
            codeFileName = optarg;
            break;
          case 'a':
            arenaSize = strtol(optarg, NULL, 0);
            break;
          case 'h':
          default:
            usage();
            return -1;
        }
    }

  if (!modelFileName || !codeFileName)
    {
      usage();
      return -1;
    }

  std::ifstream ifs(modelFileName, std::ios::binary);
  ifs.seekg(0, std::ios::end);
  size_t modelSize = ifs.tellg();
  std::unique_ptr<uint8_t[]> pModel(new uint8_t[modelSize]);

  ifs.seekg(0, std::ios::beg);
  ifs.read(reinterpret_cast<char*>(pModel.get()), modelSize);
  ifs.close();

  /* HACK: can change operators here. */

  tflite::MicroMutableOpResolver<8> resolver;
  resolver.AddConv2D(tflite::Register_CONV_2D_INT8());
  resolver.AddMaxPool2D(tflite::Register_MAX_POOL_2D_INT8());
  resolver.AddQuantize(tflite::Register_QUANTIZE_FLOAT32_INT8());
  resolver.AddDequantize(tflite::Register_DEQUANTIZE_INT8());
  resolver.AddMean(tflite::Register_MEAN_INT8());
  resolver.AddReshape();
  resolver.AddFullyConnected(tflite::Register_FULLY_CONNECTED_INT8());
  resolver.AddSoftmax(tflite::Register_SOFTMAX_INT8());

  std::unique_ptr<uint8_t[]> pArena(new uint8_t[arenaSize]);

  tflite::MicroProfiler profiler;
  tflite::MicroInterpreter interpreter(tflite::GetModel(pModel.get()),
    resolver, pArena.get(), arenaSize, nullptr,
    reinterpret_cast<tflite::MicroProfilerInterface*>(&profiler));

  /* HACK: can add testcases here. */

  if (need_invoke)
    {
      interpreter.Invoke();
      profiler.LogCsv();
      profiler.LogTicksPerTagCsv();
    }

  if (need_compile)
    {
#ifdef TFLITE_MODEL_COMPILER
      std::ofstream ofs(codeFileName);
      interpreter.Compile(ofs, prefix);
      ofs.close();
#else
      printf("Not supported compiling %s.\n", prefix);
#endif
    }

  printf("nxai done!\n");
  return 0;
}# TFLite Micro Benchmarking Tool
This CMake-based tool can be used to benchmark any TfLite format model within the NuttX environment. The tool is designed to work with the NuttX build system and supports compiling models directly into the application.

## Features
- **Built-in Model Compilation**: Models are compiled directly into the application binary
- **Memory Profiling**: Detailed memory allocation tracking and reporting
- **Timing Metrics**: Operator-level performance profiling
- **Multi-platform Support**: Works with various NuttX targets (x86, Cortex-M, Xtensa)
- **Compression Support**: Optional model compression capabilities
- **Metadata Collection**: Compiler information, target details, and model analysis

## Output Information
The tool provides comprehensive profiling data including:
- Compiler version and flags used during compilation
- Target platform information
- Model analysis (when built with model compilation)
- CRC32 checksums of input and output tensors
- Detailed timing for each operator and inference phases
- Memory arena usage and allocation statistics
- Tensor decompression timing (for compressed models)

# Build Configuration

The benchmarking tool is configured through NuttX's Kconfig system. Enable the following options in `menuconfig`:

## Required Configuration
```
Application Configuration → Machine Learning → TFLiteMicro →
    [*] TFLiteMicro
    [*] tflite-micro benchmarking tool
```

## Optional Configuration
```
Application Configuration → Machine Learning → TFLiteMicro → tflite-micro benchmarking tool →
    (100) tflite-micro benchmarking tool priority
    (10240) tflite-micro benchmarking tool stacksize
    ("") tflite model path  # Path to .tflite model file (absolute or relative)
    (32768) arena size for tensors  # Tensor arena size in bytes
```

### Key Configuration Variables
- **`CONFIG_TFLITEMICRO_BENCHMARK_TOOL`**: Enable the benchmarking tool
- **`CONFIG_BENCHMARK_MODEL_PATH`**: Path to the TfLite model file (optional, compiled model path, default: "")
- **`CONFIG_BENCHMARK_TENSOR_ARENA_SIZE`**: Size of the TFLM interpreter arena in bytes (optional, default: 32768)

## Tested targets
* x86
* Xtensa (p6, hifi3, hifi5)
* cortex_m_corstone_300 (ethos u55 npu)

## Use with compressed models
When the tool is used with compressed models, additional profiling timing will
be output.  This will consist of profiling timing for each tensor decompressed
during inference,
and a summary total.  While this profiling timing is output separately, the
timing for decompression is also included in the normal inference profiling
timing and summary total.

To use the tool with a compressed model, you can set the following variables:
* `USE_TFLM_COMPRESSION=1`
* `GENERIC_BENCHMARK_ALT_MEM_ATTR`: a C++ attribute specifying the alternate
memory as mapped through a linker script.
* `GENERIC_BENCHMARK_ALT_MEM_SIZE`: the alternate memory region size in bytes.

For more information on model compression, please see the
[compression document](https://github.com/tensorflow/tflite-micro/blob/main/tensorflow/lite/micro/docs/compression.md).

## Building with NuttX

### Step 1: Configure the build and save to <board>/.config
```bash
cd /path/to/project-root
source build/envsetup.sh
lunch <board>
m menuconfig
```

### Step 2: Enable TFLite Micro and Benchmarking Tool
Navigate to:
```
Application Configuration → Machine Learning → TFLiteMicro
```
Enable the following options:
- `[*] TFLiteMicro`
- `[*] tflite-micro benchmarking tool`

### Step 3: Configure Benchmarking Parameters
Under the benchmarking tool configuration:
- Set `tflite model path` to the path of your .tflite file which will be compiled into a binary array, or pass the path as a command-line argument(required filesystem support).
- Adjust `arena size for tensors` as needed (default: 32768)
- Configure priority and stacksize if required

### Step 4: Build and Flash
```bash
m
```

### Step 5: Run the Benchmark
```bash
# On the target device:
tflm_benchmark
```

## Example Build Scenarios

### For simulator on x86 platform:
```bash
source build/envsetup.sh
lunch ./vendor/sim/boards/vela/configs/vela/ 
m menuconfig # To enable TFLite Micro and Benchmarking Tool in menuconfig
m
```

