bool parse_count(const char* value, int* result, bool allow_zero) {
  char* end = nullptr;
  long parsed;

  errno = 0;
  parsed = strtol(value, &end, 10);
  if (errno != 0 || end == value || *end != '\0' || parsed < 0 ||
      (!allow_zero && parsed == 0) || parsed > 10000) {
    return false;
  }

  *result = static_cast<int>(parsed);
  return true;
}

extern "C" int main(int argc, FAR char* argv[]) {
  tflite::BenchmarkOptions options;
  const char* model_filename = nullptr;
  tflite::InitializeTarget();

  for (int i = 1; i < argc; ++i) {
    if (std::strcmp(argv[i], "--csv") == 0) {
      options.print_type = tflite::PrettyPrintType::kCsv;
    } else if (std::strcmp(argv[i], "--warmup") == 0 ||
               std::strcmp(argv[i], "--repeat") == 0) {
      int* value = std::strcmp(argv[i], "--warmup") == 0
                       ? &options.warmup_count
                       : &options.repeat_count;
      const bool allow_zero = value == &options.warmup_count;
      if (++i >= argc || !parse_count(argv[i], value, allow_zero)) {
        usage(argv[0]);
        return -1;
      }
    } else {
#if !defined(GENERIC_BENCHMARK_USING_BUILTIN_MODEL) && \
    !defined(GENERIC_BENCHMARK_USE_AUDIO_EVENT_MODEL)
      if (model_filename == nullptr) {
        model_filename = argv[i];
      } else {
        usage(argv[0]);
        return -1;
      }
#else
      usage(argv[0]);
      return -1;
#endif
    }
  }

#if !defined(GENERIC_BENCHMARK_USING_BUILTIN_MODEL) && \
    !defined(GENERIC_BENCHMARK_USE_AUDIO_EVENT_MODEL)
  if (model_filename == nullptr) {
    usage(argv[0]);
    return -1;
  }

  alignas(16) static uint8_t model_data[tflite::kModelSize];

  if (!tflite::ReadFile(model_filename, model_data, tflite::kModelSize)) {
    return -1;
  }
#else
  const uint8_t* model_data = MODEL_DATA;
#endif  // !defined(GENERIC_BENCHMARK_USING_BUILTIN_MODEL) &&
        // !defined(GENERIC_BENCHMARK_USE_AUDIO_EVENT_MODEL)

  MicroPrintf("\nConfigured arena size = %d\n", tflite::kTensorArenaSize);
  tflite::GenericBenchmarkShowMetaData();
  return tflite::Benchmark(model_data, options);
}
